"""Record actual matched MSVC Release compilation, not just directory names."""
from pathlib import Path
import argparse
import hashlib
import json
import subprocess

ROOT = Path(__file__).resolve().parents[1]
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--output', type=Path, required=True)
args = parser.parse_args()
examples = {}
for role in ('x86', 'x64', 'x86_server'):
    commands = json.loads((ROOT / f'.deps/dxvk-remix/bridge/_compRelease_{role}/compile_commands.json').read_text())
    actual = [item['command'] for item in commands if item['file'].endswith('.cpp')]
    if not actual or not all('/O2' in line and 'NDEBUG' in line and 'DEBUGOPT' not in line for line in actual):
        raise RuntimeError('Expected actual /O2 NDEBUG Release compilation: ' + role)
    examples[role] = actual[0]
sha = hashlib.sha256((ROOT / 'patches/l4d2-bridge.patch').read_bytes()).hexdigest()
receipt = dict(build_id='l4d2-' + (ROOT / 'VERSION').read_text().strip() + '+' + sha[:16],
               patch_sha256=sha, source_commit=subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=ROOT, text=True).strip(),
               compiler='MSVC 14.29', build_type='Release', compile_examples=examples,
               ipc='full-v2', protocol_version='0x00020004', default_batch=8,
               vbib_mapped_shadow_default=False, steam_source='876cccd419d7bca214c90fb83e66ede23a63edb4')
args.output.parent.mkdir(parents=True, exist_ok=True)
args.output.write_text(json.dumps(receipt, indent=2) + '\n')
print(receipt['build_id'])
